using Translation.Bridge.Core.Models;

namespace Translation.Bridge.Core.Interface;

/// <summary>從 InnerTube player API 拿到的日文字幕下載結果。</summary>
/// <param name="LanguageCode">選到的字幕軌語言（ja 或 ja-開頭）。</param>
/// <param name="IsAutoGenerated">是否為自動產生（asr）的字幕軌。</param>
/// <param name="ClientName">成功取得字幕的用戶端身分（VISIONOS／IOS）。</param>
/// <param name="Cues">字幕段落（依 StartMs 排序）。</param>
public sealed record YouTubeCaptionResult(string LanguageCode, bool IsAutoGenerated, string ClientName, IReadOnlyList<CaptionCue> Cues);

/// <summary>以 App 用戶端身分（visionOS、iOS）呼叫 InnerTube player API 下載 YouTube 影片的日文字幕。</summary>
public interface IYouTubeCaptionProvider
{
    /// <summary>依序試 visionOS（需 visitorData）與 iOS 身分；查不到、逾時、網路錯誤或沒有日文字幕時回傳 null，不擲例外。</summary>
    Task<YouTubeCaptionResult?> GetJapaneseCaptionsAsync(string videoId, string? visitorData, CancellationToken cancellationToken = default);
}
